declare
  v_examples jsonb := $n5_examples$[{"jlpt_level":"N5","sort_order":1,"additional_examples":[{"japanese":"私は会社員です。","romaji":"Watashi wa kaishain desu.","meaning":"I am an office worker."},{"japanese":"田中さんは先生です。","romaji":"Tanaka-san wa sensei desu.","meaning":"Tanaka is a teacher."},{"japanese":"あれは病院です。","romaji":"Are wa byouin desu.","meaning":"That over there is a hospital."},{"japanese":"山田さんは日本人です。","romaji":"Yamada-san wa nihonjin desu.","meaning":"Yamada is Japanese."}]},{"jlpt_level":"N5","sort_order":2,"additional_examples":[{"japanese":"彼は学生じゃありません。","romaji":"Kare wa gakusei ja arimasen.","meaning":"He is not a student."},{"japanese":"これは私の傘じゃありません。","romaji":"Kore wa watashi no kasa ja arimasen.","meaning":"This is not my umbrella."},{"japanese":"母は会社員じゃありません。","romaji":"Haha wa kaishain ja arimasen.","meaning":"My mother is not an office worker."},{"japanese":"あの人は医者じゃありません。","romaji":"Ano hito wa isha ja arimasen.","meaning":"That person is not a doctor."}]},{"jlpt_level":"N5","sort_order":3,"additional_examples":[{"japanese":"これは私の部屋ではありません。","romaji":"Kore wa watashi no heya dewa arimasen.","meaning":"This is not my room."},{"japanese":"田中さんは学生ではありません。","romaji":"Tanaka-san wa gakusei dewa arimasen.","meaning":"Tanaka is not a student."},{"japanese":"あの建物は学校ではありません。","romaji":"Ano tatemono wa gakkou dewa arimasen.","meaning":"That building is not a school."},{"japanese":"今日は休みではありません。","romaji":"Kyou wa yasumi dewa arimasen.","meaning":"Today is not a day off."}]},{"jlpt_level":"N5","sort_order":4,"additional_examples":[{"japanese":"去年は高校生でした。","romaji":"Kyonen wa koukousei deshita.","meaning":"I was a high school student last year."},{"japanese":"昨日はいい天気でした。","romaji":"Kinou wa ii tenki deshita.","meaning":"The weather was good yesterday."},{"japanese":"先週は休みでした。","romaji":"Senshuu wa yasumi deshita.","meaning":"Last week was a break."},{"japanese":"子どもの時、ここは公園でした。","romaji":"Kodomo no toki, koko wa kouen deshita.","meaning":"When I was a child, this place was a park."}]},{"jlpt_level":"N5","sort_order":5,"additional_examples":[{"japanese":"昨日は学校の日じゃありませんでした。","romaji":"Kinou wa gakkou no hi ja arimasen deshita.","meaning":"Yesterday was not a school day."},{"japanese":"先週は休みじゃありませんでした。","romaji":"Senshuu wa yasumi ja arimasen deshita.","meaning":"Last week was not a break."},{"japanese":"あの店は昔、レストランじゃありませんでした。","romaji":"Ano mise wa mukashi, resutoran ja arimasen deshita.","meaning":"That shop was not a restaurant in the past."},{"japanese":"日曜日は仕事の日じゃありませんでした。","romaji":"Nichiyoubi wa shigoto no hi ja arimasen deshita.","meaning":"Sunday was not a workday."}]},{"jlpt_level":"N5","sort_order":6,"additional_examples":[{"japanese":"これは新しいかばんだ。","romaji":"Kore wa atarashii kaban da.","meaning":"This is a new bag."},{"japanese":"あの人は私の兄だ。","romaji":"Ano hito wa watashi no ani da.","meaning":"That person is my older brother."},{"japanese":"今日は月曜日だ。","romaji":"Kyou wa getsuyoubi da.","meaning":"Today is Monday."},{"japanese":"ここは静かな町だ。","romaji":"Koko wa shizuka na machi da.","meaning":"This is a quiet town."}]},{"jlpt_level":"N5","sort_order":7,"additional_examples":[{"japanese":"あなたは日本人ですか。","romaji":"Anata wa nihonjin desu ka.","meaning":"Are you Japanese?"},{"japanese":"駅はここですか。","romaji":"Eki wa koko desu ka.","meaning":"Is the station here?"},{"japanese":"明日は休みですか。","romaji":"Ashita wa yasumi desu ka.","meaning":"Is tomorrow a day off?"},{"japanese":"これは田中さんの本ですか。","romaji":"Kore wa Tanaka-san no hon desu ka.","meaning":"Is this Tanaka's book?"}]},{"jlpt_level":"N5","sort_order":8,"additional_examples":[{"japanese":"私は毎朝コーヒーを飲みます。","romaji":"Watashi wa maiasa koohii o nomimasu.","meaning":"I drink coffee every morning."},{"japanese":"今日は学校へ行きません。","romaji":"Kyou wa gakkou e ikimasen.","meaning":"I am not going to school today."},{"japanese":"この町はとても静かです。","romaji":"Kono machi wa totemo shizuka desu.","meaning":"This town is very quiet."},{"japanese":"日本語はおもしろいです。","romaji":"Nihongo wa omoshiroi desu.","meaning":"Japanese is interesting."}]},{"jlpt_level":"N5","sort_order":9,"additional_examples":[{"japanese":"犬が庭にいます。","romaji":"Inu ga niwa ni imasu.","meaning":"There is a dog in the garden."},{"japanese":"雨が降っています。","romaji":"Ame ga futte imasu.","meaning":"It is raining."},{"japanese":"だれが料理をしますか。","romaji":"Dare ga ryouri o shimasu ka.","meaning":"Who will cook?"},{"japanese":"バスが来ました。","romaji":"Basu ga kimashita.","meaning":"The bus has arrived."}]},{"jlpt_level":"N5","sort_order":10,"additional_examples":[{"japanese":"私は毎日水を飲みます。","romaji":"Watashi wa mainichi mizu o nomimasu.","meaning":"I drink water every day."},{"japanese":"妹は本を読みます。","romaji":"Imouto wa hon o yomimasu.","meaning":"My younger sister reads books."},{"japanese":"父は新聞を買いました。","romaji":"Chichi wa shinbun o kaimashita.","meaning":"My father bought a newspaper."},{"japanese":"昼ご飯にうどんを食べます。","romaji":"Hirugohan ni udon o tabemasu.","meaning":"I eat udon for lunch."}]},{"jlpt_level":"N5","sort_order":11,"additional_examples":[{"japanese":"弟も高校生です。","romaji":"Otouto mo koukousei desu.","meaning":"My younger brother is also a high school student."},{"japanese":"母も日本語を勉強しています。","romaji":"Haha mo nihongo o benkyou shite imasu.","meaning":"My mother is also studying Japanese."},{"japanese":"日曜日も働きます。","romaji":"Nichiyoubi mo hatarakimasu.","meaning":"I work on Sundays too."},{"japanese":"この店のパンもおいしいです。","romaji":"Kono mise no pan mo oishii desu.","meaning":"The bread at this shop is delicious too."}]},{"jlpt_level":"N5","sort_order":12,"additional_examples":[{"japanese":"これは妹の自転車です。","romaji":"Kore wa imouto no jitensha desu.","meaning":"This is my younger sister's bicycle."},{"japanese":"日本語の先生は親切です。","romaji":"Nihongo no sensei wa shinsetsu desu.","meaning":"The Japanese teacher is kind."},{"japanese":"あれは学校の時計です。","romaji":"Are wa gakkou no tokei desu.","meaning":"That is the school's clock."},{"japanese":"父の車は大きいです。","romaji":"Chichi no kuruma wa ookii desu.","meaning":"My father's car is big."}]},{"jlpt_level":"N5","sort_order":13,"additional_examples":[{"japanese":"毎朝六時に起きます。","romaji":"Maiasa roku-ji ni okimasu.","meaning":"I get up at six every morning."},{"japanese":"授業は九時に始まります。","romaji":"Jugyou wa ku-ji ni hajimarimasu.","meaning":"The class starts at nine."},{"japanese":"夜十一時に寝ます。","romaji":"Yoru juuichi-ji ni nemasu.","meaning":"I go to bed at eleven at night."},{"japanese":"月曜日に病院へ行きます。","romaji":"Getsuyoubi ni byouin e ikimasu.","meaning":"I go to the hospital on Monday."}]},{"jlpt_level":"N5","sort_order":14,"additional_examples":[{"japanese":"友達は駅に来ます。","romaji":"Tomodachi wa eki ni kimasu.","meaning":"My friend comes to the station."},{"japanese":"毎日会社に行きます。","romaji":"Mainichi kaisha ni ikimasu.","meaning":"I go to the office every day."},{"japanese":"夜、家に帰ります。","romaji":"Yoru, ie ni kaerimasu.","meaning":"I return home at night."},{"japanese":"来週、京都に行きます。","romaji":"Raishuu, Kyoto ni ikimasu.","meaning":"I am going to Kyoto next week."}]},{"jlpt_level":"N5","sort_order":15,"additional_examples":[{"japanese":"公園に大きい木があります。","romaji":"Kouen ni ookii ki ga arimasu.","meaning":"There is a big tree in the park."},{"japanese":"教室に先生がいます。","romaji":"Kyoushitsu ni sensei ga imasu.","meaning":"There is a teacher in the classroom."},{"japanese":"冷蔵庫に牛乳があります。","romaji":"Reizouko ni gyuunyuu ga arimasu.","meaning":"There is milk in the refrigerator."},{"japanese":"駅の前に銀行があります。","romaji":"Eki no mae ni ginkou ga arimasu.","meaning":"There is a bank in front of the station."}]},{"jlpt_level":"N5","sort_order":16,"additional_examples":[{"japanese":"来月、家族と大阪へ行きます。","romaji":"Raigetsu, kazoku to Osaka e ikimasu.","meaning":"I am going to Osaka with my family next month."},{"japanese":"子どもたちは学校へ歩きます。","romaji":"Kodomotachi wa gakkou e arukimasu.","meaning":"The children walk toward school."},{"japanese":"このバスは空港へ行きます。","romaji":"Kono basu wa kuukou e ikimasu.","meaning":"This bus goes to the airport."},{"japanese":"友達は日本へ帰りました。","romaji":"Tomodachi wa Nihon e kaerimashita.","meaning":"My friend returned to Japan."}]},{"jlpt_level":"N5","sort_order":17,"additional_examples":[{"japanese":"食堂で昼ご飯を食べます。","romaji":"Shokudou de hirugohan o tabemasu.","meaning":"I eat lunch in the cafeteria."},{"japanese":"公園でサッカーをします。","romaji":"Kouen de sakkaa o shimasu.","meaning":"I play soccer in the park."},{"japanese":"家で日本語を勉強します。","romaji":"Ie de nihongo o benkyou shimasu.","meaning":"I study Japanese at home."},{"japanese":"駅で友達に会いました。","romaji":"Eki de tomodachi ni aimashita.","meaning":"I met my friend at the station."}]},{"jlpt_level":"N5","sort_order":18,"additional_examples":[{"japanese":"ペンで名前を書きます。","romaji":"Pen de namae o kakimasu.","meaning":"I write my name with a pen."},{"japanese":"箸で魚を食べます。","romaji":"Hashi de sakana o tabemasu.","meaning":"I eat fish with chopsticks."},{"japanese":"電車で会社へ行きます。","romaji":"Densha de kaisha e ikimasu.","meaning":"I go to work by train."},{"japanese":"日本語で手紙を書きました。","romaji":"Nihongo de tegami o kakimashita.","meaning":"I wrote a letter in Japanese."}]},{"jlpt_level":"N5","sort_order":19,"additional_examples":[{"japanese":"週末、友達と買い物をします。","romaji":"Shuumatsu, tomodachi to kaimono o shimasu.","meaning":"I go shopping with a friend on the weekend."},{"japanese":"姉と映画を見ました。","romaji":"Ane to eiga o mimashita.","meaning":"I watched a movie with my older sister."},{"japanese":"母とスーパーへ行きます。","romaji":"Haha to suupaa e ikimasu.","meaning":"I go to the supermarket with my mother."},{"japanese":"先生と日本語を話します。","romaji":"Sensei to nihongo o hanashimasu.","meaning":"I speak Japanese with the teacher."}]},{"jlpt_level":"N5","sort_order":20,"additional_examples":[{"japanese":"机の上に本とノートがあります。","romaji":"Tsukue no ue ni hon to nooto ga arimasu.","meaning":"There is a book and a notebook on the desk."},{"japanese":"朝ご飯に卵とパンを食べます。","romaji":"Asagohan ni tamago to pan o tabemasu.","meaning":"I eat eggs and bread for breakfast."},{"japanese":"兄と妹がいます。","romaji":"Ani to imouto ga imasu.","meaning":"I have an older brother and a younger sister."},{"japanese":"りんごとバナナを買いました。","romaji":"Ringo to banana o kaimashita.","meaning":"I bought apples and bananas."}]},{"jlpt_level":"N5","sort_order":21,"additional_examples":[{"japanese":"これは母の時計です。","romaji":"Kore wa haha no tokei desu.","meaning":"This is my mother's watch."},{"japanese":"それは駅の地図です。","romaji":"Sore wa eki no chizu desu.","meaning":"That is a map of the station."},{"japanese":"あれは私の学校です。","romaji":"Are wa watashi no gakkou desu.","meaning":"That over there is my school."},{"japanese":"これは日本語の辞書です。","romaji":"Kore wa nihongo no jisho desu.","meaning":"This is a Japanese dictionary."}]},{"jlpt_level":"N5","sort_order":22,"additional_examples":[{"japanese":"この店は安いです。","romaji":"Kono mise wa yasui desu.","meaning":"This shop is inexpensive."},{"japanese":"そのかばんはだれのですか。","romaji":"Sono kaban wa dare no desu ka.","meaning":"Whose bag is that?"},{"japanese":"あの山は高いです。","romaji":"Ano yama wa takai desu.","meaning":"That mountain over there is high."},{"japanese":"この映画はおもしろいです。","romaji":"Kono eiga wa omoshiroi desu.","meaning":"This movie is interesting."}]},{"jlpt_level":"N5","sort_order":23,"additional_examples":[{"japanese":"ここに名前を書いてください。","romaji":"Koko ni namae o kaite kudasai.","meaning":"Please write your name here."},{"japanese":"そこは駅の入口です。","romaji":"Soko wa eki no iriguchi desu.","meaning":"There is the station entrance."},{"japanese":"あそこに郵便局があります。","romaji":"Asoko ni yuubinkyoku ga arimasu.","meaning":"There is a post office over there."},{"japanese":"ここで写真を撮ります。","romaji":"Koko de shashin o torimasu.","meaning":"I will take a photo here."}]},{"jlpt_level":"N5","sort_order":24,"additional_examples":[{"japanese":"トイレはどこですか。","romaji":"Toire wa doko desu ka.","meaning":"Where is the restroom?"},{"japanese":"田中さんはどこにいますか。","romaji":"Tanaka-san wa doko ni imasu ka.","meaning":"Where is Tanaka?"},{"japanese":"この近くに銀行はどこにありますか。","romaji":"Kono chikaku ni ginkou wa doko ni arimasu ka.","meaning":"Where is a bank near here?"},{"japanese":"駅はどこですか。","romaji":"Eki wa doko desu ka.","meaning":"Where is the station?"}]},{"jlpt_level":"N5","sort_order":25,"additional_examples":[{"japanese":"あの先生はだれですか。","romaji":"Ano sensei wa dare desu ka.","meaning":"Who is that teacher?"},{"japanese":"だれが窓を開けましたか。","romaji":"Dare ga mado o akemashita ka.","meaning":"Who opened the window?"},{"japanese":"この写真の人はだれですか。","romaji":"Kono shashin no hito wa dare desu ka.","meaning":"Who is the person in this photo?"},{"japanese":"だれと学校へ行きますか。","romaji":"Dare to gakkou e ikimasu ka.","meaning":"Who will you go to school with?"}]},{"jlpt_level":"N5","sort_order":26,"additional_examples":[{"japanese":"何を食べますか。","romaji":"Nani o tabemasu ka.","meaning":"What will you eat?"},{"japanese":"あの人は何をしていますか。","romaji":"Ano hito wa nani o shite imasu ka.","meaning":"What is that person doing?"},{"japanese":"これは何の本ですか。","romaji":"Kore wa nan no hon desu ka.","meaning":"What kind of book is this?"},{"japanese":"何時に帰りますか。","romaji":"Nan-ji ni kaerimasu ka.","meaning":"What time will you return?"}]},{"jlpt_level":"N5","sort_order":27,"additional_examples":[{"japanese":"あなたの靴はどれですか。","romaji":"Anata no kutsu wa dore desu ka.","meaning":"Which ones are your shoes?"},{"japanese":"どれが一番大きいですか。","romaji":"Dore ga ichiban ookii desu ka.","meaning":"Which one is the biggest?"},{"japanese":"私の傘はどれですか。","romaji":"Watashi no kasa wa dore desu ka.","meaning":"Which one is my umbrella?"},{"japanese":"この中でどれが好きですか。","romaji":"Kono naka de dore ga suki desu ka.","meaning":"Which one do you like among these?"}]},{"jlpt_level":"N5","sort_order":28,"additional_examples":[{"japanese":"どの電車に乗りますか。","romaji":"Dono densha ni norimasu ka.","meaning":"Which train will you take?"},{"japanese":"どの人が田中さんですか。","romaji":"Dono hito ga Tanaka-san desu ka.","meaning":"Which person is Tanaka?"},{"japanese":"どの本を買いましたか。","romaji":"Dono hon o kaimashita ka.","meaning":"Which book did you buy?"},{"japanese":"どの店で昼ご飯を食べますか。","romaji":"Dono mise de hirugohan o tabemasu ka.","meaning":"At which shop will you eat lunch?"}]},{"jlpt_level":"N5","sort_order":29,"additional_examples":[{"japanese":"どんな映画が好きですか。","romaji":"Donna eiga ga suki desu ka.","meaning":"What kind of movies do you like?"},{"japanese":"どんな音楽を聞きますか。","romaji":"Donna ongaku o kikimasu ka.","meaning":"What kind of music do you listen to?"},{"japanese":"どんな町に住みたいですか。","romaji":"Donna machi ni sumitai desu ka.","meaning":"What kind of town would you like to live in?"},{"japanese":"どんな食べ物をよく食べますか。","romaji":"Donna tabemono o yoku tabemasu ka.","meaning":"What kind of food do you often eat?"}]},{"jlpt_level":"N5","sort_order":30,"additional_examples":[{"japanese":"試験はいつですか。","romaji":"Shiken wa itsu desu ka.","meaning":"When is the exam?"},{"japanese":"いつ日本へ行きますか。","romaji":"Itsu Nihon e ikimasu ka.","meaning":"When will you go to Japan?"},{"japanese":"田中さんはいつ来ますか。","romaji":"Tanaka-san wa itsu kimasu ka.","meaning":"When will Tanaka come?"},{"japanese":"誕生日はいつですか。","romaji":"Tanjoubi wa itsu desu ka.","meaning":"When is your birthday?"}]},{"jlpt_level":"N5","sort_order":31,"additional_examples":[{"japanese":"この料理はどうですか。","romaji":"Kono ryouri wa dou desu ka.","meaning":"How is this dish?"},{"japanese":"学校の生活はどうですか。","romaji":"Gakkou no seikatsu wa dou desu ka.","meaning":"How is school life?"},{"japanese":"この漢字をどう読みますか。","romaji":"Kono kanji o dou yomimasu ka.","meaning":"How do you read this kanji?"},{"japanese":"駅までどうやって行きますか。","romaji":"Eki made dou yatte ikimasu ka.","meaning":"How do you get to the station?"}]},{"jlpt_level":"N5","sort_order":32,"additional_examples":[{"japanese":"この時計はいくらですか。","romaji":"Kono tokei wa ikura desu ka.","meaning":"How much is this watch?"},{"japanese":"りんごは一ついくらですか。","romaji":"Ringo wa hitotsu ikura desu ka.","meaning":"How much is one apple?"},{"japanese":"その靴はいくらでしたか。","romaji":"Sono kutsu wa ikura deshita ka.","meaning":"How much were those shoes?"},{"japanese":"この切符はいくらですか。","romaji":"Kono kippu wa ikura desu ka.","meaning":"How much is this ticket?"}]},{"jlpt_level":"N5","sort_order":33,"additional_examples":[{"japanese":"子どもは何歳ですか。","romaji":"Kodomo wa nansai desu ka.","meaning":"How old is the child?"},{"japanese":"りんごはいくつありますか。","romaji":"Ringo wa ikutsu arimasu ka.","meaning":"How many apples are there?"},{"japanese":"卵をいくつ買いますか。","romaji":"Tamago o ikutsu kaimasu ka.","meaning":"How many eggs will you buy?"},{"japanese":"妹は今年いくつですか。","romaji":"Imouto wa kotoshi ikutsu desu ka.","meaning":"How old is my younger sister this year?"}]},{"jlpt_level":"N5","sort_order":34,"additional_examples":[{"japanese":"どうして今日は休みですか。","romaji":"Doushite kyou wa yasumi desu ka.","meaning":"Why is today a day off?"},{"japanese":"どうして日本語を勉強しますか。","romaji":"Doushite nihongo o benkyou shimasu ka.","meaning":"Why do you study Japanese?"},{"japanese":"どうして遅くなりましたか。","romaji":"Doushite osoku narimashita ka.","meaning":"Why did you become late?"},{"japanese":"どうしてその店へ行きますか。","romaji":"Doushite sono mise e ikimasu ka.","meaning":"Why do you go to that shop?"}]},{"jlpt_level":"N5","sort_order":35,"additional_examples":[{"japanese":"毎晩、本を読みます。","romaji":"Maiban, hon o yomimasu.","meaning":"I read a book every night."},{"japanese":"母は朝ご飯を作ります。","romaji":"Haha wa asagohan o tsukurimasu.","meaning":"My mother makes breakfast."},{"japanese":"日曜日に友達に会います。","romaji":"Nichiyoubi ni tomodachi ni aimasu.","meaning":"I meet a friend on Sunday."},{"japanese":"駅まで歩きます。","romaji":"Eki made arukimasu.","meaning":"I walk to the station."}]},{"jlpt_level":"N5","sort_order":36,"additional_examples":[{"japanese":"私は魚を食べません。","romaji":"Watashi wa sakana o tabemasen.","meaning":"I do not eat fish."},{"japanese":"今日はテレビを見ません。","romaji":"Kyou wa terebi o mimasen.","meaning":"I do not watch television today."},{"japanese":"弟はコーヒーを飲みません。","romaji":"Otouto wa koohii o nomimasen.","meaning":"My younger brother does not drink coffee."},{"japanese":"日曜日は学校へ行きません。","romaji":"Nichiyoubi wa gakkou e ikimasen.","meaning":"I do not go to 