t_order":45,"additional_examples":[{"japanese":"昨日、友達と話した。","romaji":"Kinou, tomodachi to hanashita.","meaning":"I talked with a friend yesterday."},{"japanese":"先週、京都へ行った。","romaji":"Senshuu, Kyoto e itta.","meaning":"I went to Kyoto last week."},{"japanese":"朝ご飯を食べた。","romaji":"Asagohan o tabeta.","meaning":"I ate breakfast."},{"japanese":"昨日、新しい本を買った。","romaji":"Kinou, atarashii hon o katta.","meaning":"I bought a new book yesterday."}]},{"jlpt_level":"N5","sort_order":46,"additional_examples":[{"japanese":"ここに住所を書いてください。","romaji":"Koko ni juusho o kaite kudasai.","meaning":"Please write your address here."},{"japanese":"ゆっくり話してください。","romaji":"Yukkuri hanashite kudasai.","meaning":"Please speak slowly."},{"japanese":"窓を閉めてください。","romaji":"Mado o shimete kudasai.","meaning":"Please close the window."},{"japanese":"もう一度読んでください。","romaji":"Mou ichido yonde kudasai.","meaning":"Please read it one more time."}]},{"jlpt_level":"N5","sort_order":47,"additional_examples":[{"japanese":"ここに車を止めないでください。","romaji":"Koko ni kuruma o tomenaide kudasai.","meaning":"Please do not park a car here."},{"japanese":"この水を飲まないでください。","romaji":"Kono mizu o nomanaide kudasai.","meaning":"Please do not drink this water."},{"japanese":"授業中に話さないでください。","romaji":"Jugyou chuu ni hanasanaide kudasai.","meaning":"Please do not talk during class."},{"japanese":"ドアを開けないでください。","romaji":"Doa o akenaide kudasai.","meaning":"Please do not open the door."}]},{"jlpt_level":"N5","sort_order":48,"additional_examples":[{"japanese":"一緒に昼ご飯を食べましょう。","romaji":"Issho ni hirugohan o tabemashou.","meaning":"Let's eat lunch together."},{"japanese":"駅まで歩きましょう。","romaji":"Eki made arukimashou.","meaning":"Let's walk to the station."},{"japanese":"明日、日本語を勉強しましょう。","romaji":"Ashita, nihongo o benkyou shimashou.","meaning":"Let's study Japanese tomorrow."},{"japanese":"少し休みましょう。","romaji":"Sukoshi yasumimashou.","meaning":"Let's rest for a while."}]},{"jlpt_level":"N5","sort_order":49,"additional_examples":[{"japanese":"週末、海へ行きませんか。","romaji":"Shuumatsu, umi e ikimasen ka.","meaning":"Would you like to go to the sea this weekend?"},{"japanese":"一緒にコーヒーを飲みませんか。","romaji":"Issho ni koohii o nomimasen ka.","meaning":"Would you like to have coffee together?"},{"japanese":"今夜、映画を見ませんか。","romaji":"Konya, eiga o mimasen ka.","meaning":"Would you like to watch a movie tonight?"},{"japanese":"明日、公園でテニスをしませんか。","romaji":"Ashita, kouen de tenisu o shimasen ka.","meaning":"Would you like to play tennis in the park tomorrow?"}]},{"jlpt_level":"N5","sort_order":50,"additional_examples":[{"japanese":"荷物を持ちましょうか。","romaji":"Nimotsu o mochimashou ka.","meaning":"Shall I carry your luggage?"},{"japanese":"窓を開けましょうか。","romaji":"Mado o akemashou ka.","meaning":"Shall I open the window?"},{"japanese":"駅まで一緒に行きましょうか。","romaji":"Eki made issho ni ikimashou ka.","meaning":"Shall I go with you to the station?"},{"japanese":"もう一度説明しましょうか。","romaji":"Mou ichido setsumei shimashou ka.","meaning":"Shall I explain it one more time?"}]},{"jlpt_level":"N5","sort_order":51,"additional_examples":[{"japanese":"妹は今、宿題をしています。","romaji":"Imouto wa ima, shukudai o shite imasu.","meaning":"My younger sister is doing her homework now."},{"japanese":"父は新聞を読んでいます。","romaji":"Chichi wa shinbun o yonde imasu.","meaning":"My father is reading a newspaper."},{"japanese":"子どもたちは公園で遊んでいます。","romaji":"Kodomotachi wa kouen de asonde imasu.","meaning":"The children are playing in the park."},{"japanese":"母は電話で話しています。","romaji":"Haha wa denwa de hanashite imasu.","meaning":"My mother is talking on the phone."}]},{"jlpt_level":"N5","sort_order":52,"additional_examples":[{"japanese":"手を洗ってから、ご飯を食べます。","romaji":"Te o aratte kara, gohan o tabemasu.","meaning":"I wash my hands before eating."},{"japanese":"宿題をしてから、テレビを見ます。","romaji":"Shukudai o shite kara, terebi o mimasu.","meaning":"I watch television after doing my homework."},{"japanese":"シャワーを浴びてから寝ます。","romaji":"Shawaa o abite kara nemasu.","meaning":"I go to bed after taking